prompt --application/shared_components/ai_agent/procurement_agent
begin
wwv_flow_imp_shared.create_ai_agent(
 p_id=>wwv_flow_imp.id(1506591746273732840)
,p_name=>'Procurement Agent'
,p_static_id=>'procurement-agent'
,p_remote_server_id=>1505835551950679122
,p_system_prompt=>wwv_flow_string.join(wwv_flow_t_varchar2(
'You are a procurement assistant for the APEX Inventory and Warehouse Management application.',
'Your role is to:',
'- Identify items at risk in the current user''s warehouse',
'- Explain the severity of the risk using available stock, reorder policy, alert priority, and lead time',
'- Find suppliers who have previously supplied the selected item',
'- Compare supplier performance before recommending a supplier',
'- Collect the warehouse, quantity, and due date needed for a purchase order',
'- Execute actions only after the user confirms',
'',
'Always prioritise:',
'- CRITICAL and HIGH stock-risk items',
'- Items at or below reorder point',
'- Items with open replenishment alerts and short or threatened lead time',
'- Supplier recommendations with stronger on-time and quality performance',
'',
'When the user asks to raise a purchase order:',
'- Default to the user''s warehouse from get_user_context. Only call show_warehouses_by_supplier and ask the user to choose a different warehouse if the user''s role scope is not warehouse-specific or the user explicitly requests a different warehouse.',
'- Ask how many units are needed',
'- Ask when delivery is required',
'- Convert any relative date the user gives ("next Tuesday", "end of month") to YYYY-MM-DD using today''s date before passing as DUE_DATE',
'- Do not invent supplier, warehouse, quantity, or due date',
'- Use full_name from get_user_context as the PO owner'))
,p_welcome_message=>'Hi, I''m your Procurement Assistant. How can I help you today?'
,p_version_scn=>'SH256:h0-TtIVkaoNhAibrRfdBvUFBQvU_vc0kBwaJ8zsCSMk'
,p_created_on=>wwv_flow_imp.dz('20261009091326Z')
,p_updated_on=>wwv_flow_imp.dz('20261009093613Z')
,p_created_by=>'SCM-GENDEV-USER'
,p_updated_by=>'SCM-GENDEV-USER'
);
wwv_flow_imp_shared.create_ai_agent_tool(
 p_id=>wwv_flow_imp.id(1507805118392755800)
,p_tool_name=>'get_browser_timezone'
,p_static_id=>'get-browser-timezone'
,p_tool_type=>'NATIVE_EXECUTE_CLIENT_SIDE_CODE'
,p_execution_point=>'AUGMENT_SYSTEM_PROMPT'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', 'return Intl.DateTimeFormat().resolvedOptions().timeZone;')).to_clob
,p_created_on=>wwv_flow_imp.dz('20261009091716Z')
,p_updated_on=>wwv_flow_imp.dz('20261009091716Z')
,p_created_by=>'SCM-GENDEV-USER'
,p_updated_by=>'SCM-GENDEV-USER'
);
wwv_flow_imp_shared.create_ai_agent_tool(
 p_id=>wwv_flow_imp.id(1508379565836776156)
,p_tool_name=>'get_stocks_at_risk'
,p_static_id=>'get-stocks-at-risk'
,p_tool_type=>'NATIVE_RETRIEVE_DATA'
,p_execution_point=>'ON_DEMAND'
,p_description=>'Returns items in the current user''s warehouse that are at or below their reorder point, or have an open replenishment alert. Call this when the user asks about stock risk, low stock, or what needs attention. Returns item name, available quantity, reo'
||'rder point, alert priority, and supplier lead time. Results are ordered by priority then by gap size.'
,p_requires_confirmation=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'sql_query', wwv_flow_string.join(wwv_flow_t_varchar2(
    'select item_id,',
    '       item_code,',
    '       item_name,',
    '       base_uom_code,',
    '       warehouse_name,',
    '       available_quantity,',
    '       reorder_point_quantity,',
    '       safety_stock_quantity,',
    '       reorder_target_quantity,',
    '       replenishment_lead_time_days,',
    '       alert_priority,',
    '       alert_type_code,',
    '       alert_number,',
    '       hours_open',
    '  from scm_v_stocks_at_risk',
    ' where lower(user_name) = lower(:APP_USER)',
    ' order by priority_sort, stock_gap desc',
    '')),
  'type', 'SQL_QUERY')).to_clob
,p_created_on=>wwv_flow_imp.dz('20261009092040Z')
,p_updated_on=>wwv_flow_imp.dz('20261009092040Z')
,p_created_by=>'SCM-GENDEV-USER'
,p_updated_by=>'SCM-GENDEV-USER'
);
wwv_flow_imp_shared.create_ai_agent_tool(
 p_id=>wwv_flow_imp.id(1509033911176862377)
,p_tool_name=>'get_supplier_delivery_performance'
,p_static_id=>'get-supplier-delivery-performance'
,p_tool_type=>'NATIVE_RETRIEVE_DATA'
,p_execution_point=>'ON_DEMAND'
,p_description=>'Returns a detailed delivery performance scorecard for a supplier over a given period. Pass supplier_id from get_suppliers_for_item. Pass TIME_PERIOD as QUARTER for last quarter or YEAR for last 12 months. Call this when the user wants to check a supp'
||'lier''s track record before raising a purchase order. Returns on-time rate, average delay, dock-to-stock time, damage rate, and total volumes.'
,p_requires_confirmation=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'sql_query', wwv_flow_string.join(wwv_flow_t_varchar2(
    'select *',
    '  from scm_v_supplier_delivery_performance',
    ' where business_partner_id = :SUPPLIER_ID',
    '   and time_period         = :TIME_PERIOD',
    '')),
  'type', 'SQL_QUERY')).to_clob
,p_created_on=>wwv_flow_imp.dz('20261009092738Z')
,p_updated_on=>wwv_flow_imp.dz('20261009092738Z')
,p_created_by=>'SCM-GENDEV-USER'
,p_updated_by=>'SCM-GENDEV-USER'
);
wwv_flow_imp_shared.create_ai_agent_tool_param(
 p_id=>wwv_flow_imp.id(1509034866801862386)
,p_param_name=>'SUPPLIER_ID'
,p_description=>'Selected supplier identifier.'
,p_data_type=>'NUMBER'
,p_is_required=>true
,p_created_on=>wwv_flow_imp.dz('20261009092738Z')
,p_updated_on=>wwv_flow_imp.dz('20261009092738Z')
,p_created_by=>'SCM-GENDEV-USER'
,p_updated_by=>'SCM-GENDEV-USER'
);
wwv_flow_imp_shared.create_ai_agent_tool_param(
 p_id=>wwv_flow_imp.id(1509034303190862383)
,p_param_name=>'TIME_PERIOD'
,p_description=>'Reporting horizon such as QUARTER or YEAR'
,p_data_type=>'VARCHAR2'
,p_is_required=>true
,p_created_on=>wwv_flow_imp.dz('20261009092738Z')
,p_updated_on=>wwv_flow_imp.dz('20261009092738Z')
,p_created_by=>'SCM-GENDEV-USER'
,p_updated_by=>'SCM-GENDEV-USER'
);
wwv_flow_imp_shared.create_ai_agent_tool(
 p_id=>wwv_flow_imp.id(1508725111969798422)
,p_tool_name=>'get_suppliers_for_item'
,p_static_id=>'get-suppliers-for-item'
,p_tool_type=>'NATIVE_RETRIEVE_DATA'
,p_execution_point=>'ON_DEMAND'
,p_description=>'Returns active suppliers who have previously supplied the given item. Pass item_id from get_stocks_at_risk. Present only supplier_name, total_receipts, last_received_at, on_time_rate_pct, and damage_rate_pct to the user. Keep supplier_id and partner_'
||'site_id internal, as they are needed as parameters for show_warehouses_by_supplier and raise_purchase_order. Results are ordered best performer first.'
,p_requires_confirmation=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'sql_query', wwv_flow_string.join(wwv_flow_t_varchar2(
    'select supplier_id,',
    '       partner_number,',
    '       supplier_name,',
    '       partner_site_id,',
    '       site_code,',
    '       site_name,',
    '       total_receipts,',
    '       last_received_at,',
    '       on_time_rate_pct,',
    '       damage_rate_pct',
    '  from scm_v_suppliers_for_item',
    ' where item_id = :ITEM_ID',
    ' order by on_time_rate_pct desc nulls last,',
    '          damage_rate_pct   asc  nulls last',
    '')),
  'type', 'SQL_QUERY')).to_clob
,p_created_on=>wwv_flow_imp.dz('20261009092422Z')
,p_updated_on=>wwv_flow_imp.dz('20261009092422Z')
