,p_tool_name=>'get_user_context'
,p_static_id=>'get-user-context'
,p_tool_type=>'NATIVE_RETRIEVE_DATA'
,p_execution_point=>'AUGMENT_SYSTEM_PROMPT'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'data_description', 'Returns the current user''s full name, role, warehouse, approval authority level, and manager. Injected automatically on every message before any reasoning begins. Use full_name as the PO owner when raising purchase orders. Use warehouse_id as the def'
||'ault warehouse context.',
  'sql_query', wwv_flow_string.join(wwv_flow_t_varchar2(
    'select *',
