'    , c.SHORTAGE_QUANTITY as SHORTAGE_QUANTITY',
'    , c.OVERAGE_QUANTITY as OVERAGE_QUANTITY',
'    , c.REJECTED_QUANTITY as REJECTED_QUANTITY',
'    , c.RECEIVED_CONDITION_CODE as RECEIVED_CONDITION_CODE',
'    , c.LINE_STATUS_CODE as LINE_STATUS_CODE',
