'select',
'    c.STOCK_TRANSFER_LINE_ID as STOCK_TRANSFER_LINE_ID',
'    , c.STOCK_TRANSFER_ID as STOCK_TRANSFER_ID',
'    , c.LINE_NUMBER as LINE_NUMBER',
'    , c.ITEM_ID as ITEM_ID',
'    , c.INVENTORY_LOT_ID as INVENTORY_LOT_ID',
'    , c.SOURCE_LOCATION_ID as SOURCE_LOCATION_ID',
'    , c.DESTINATION_LOCATION_ID as DESTINATION_LOCATION_ID',
'    , c.REQUESTED_QUANTITY as REQUESTED_QUANTITY',
'    , c.SHIPPED_QUANTITY as SHIPPED_QUANTITY',
'    , c.RECEIVED_QUANTITY as RECEIVED_QUANTITY',
'    , c.QUANTITY_DISCREPANCY as QUANTITY_DISCREPANCY',
'    , c.LINE_STATUS_CODE as LINE_STATUS_CODE',
'    , c.DISCREPANCY_REASON_CODE as DISCREPANCY_REASON_CODE',
'from SCM_STOCK_TRANSFER_LINES c',
'where',
'    c.STOCK_TRANSFER_ID = to_number(:P51_STOCK_TRANSFER_ID)',
'order by',
'    LINE_NUMBER asc'))
